import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Connect an existing Web client through Electron","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/electron-shell","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/electron-shell.md","filePath":"en/tutorials/electron-shell.md"}'),i={name:"en/tutorials/electron-shell.md"};function o(r,e,d,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="connect-an-existing-web-client-through-electron" tabindex="-1">Connect an existing Web client through Electron <a class="header-anchor" href="#connect-an-existing-web-client-through-electron" aria-label="Permalink to &quot;Connect an existing Web client through Electron&quot;">​</a></h1><p>Once your backend API and Web pages work, Electron can load the same pages, generated SDK and Session protocol. The shell handles platform wiring without adding separate business or authorization rules. Offline editing is not provided.</p><p>Prerequisites are <a href="./../getting-started/quickstart">quick start</a>, a client using your backend and Electron&#39;s desktop dependencies with a display. Run commands from the repository root.</p><h2 id="load-the-existing-application" tabindex="-1">Load the existing application <a class="header-anchor" href="#load-the-existing-application" aria-label="Permalink to &quot;Load the existing application&quot;">​</a></h2><p>Start the app in one terminal and the shell in another:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span></code></pre></div><p>The default Web address is <code>http://127.0.0.1:15400</code>; change it through <code>.env</code> values <code>SAAS_DESKTOP_ORIGIN</code> or <code>WEB_PORT</code>. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/desktop/src/main.ts" target="_blank" rel="noreferrer">main process</a> loads that same-origin entrance, while the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/web/src/router.tsx" target="_blank" rel="noreferrer">Web Router</a> and shared pages implement business. Verify sign-in, a resource read and a write, then restart the shell and read the resource again.</p><p>Cookies live in persistent partition <code>persist:saas-desktop</code>, separate from the system browser. Sign-out revokes the current server Session; only clients using that same Session lose access. An independently signed-in browser Session is not revoked by it.</p><h2 id="preserve-the-ipc-capability-boundary" tabindex="-1">Preserve the IPC capability boundary <a class="header-anchor" href="#preserve-the-ipc-capability-boundary" aria-label="Permalink to &quot;Preserve the IPC capability boundary&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/desktop/src/preload.ts" target="_blank" rel="noreferrer">Preload</a> and the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/desktop/src/ipc-contract.ts" target="_blank" rel="noreferrer">IPC contract</a> expose shell version/platform, load retry, download directory, download events and language/theme preferences. Both sides validate payloads. Business objects, credentials, Session secrets and file bytes never travel through IPC.</p><p>The window enables <code>contextIsolation</code> and <code>sandbox</code>, disables <code>nodeIntegration</code> and prohibits webviews. Navigation stays on the app origin; external http/https links open in the system browser. Popups, website permission requests and other schemes are rejected, with no certificate-error bypass. Define narrow IPC types and validation before adding platform capabilities rather than exposing arbitrary Node calls.</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/web/src/desktop-preferences.tsx" target="_blank" rel="noreferrer">desktop-preferences.tsx</a> mirrors only language and theme enums inside Electron so the <code>file://</code> error page preserves appearance. It contains no account or business data and is a no-op in a browser.</p><h2 id="wire-deep-links-and-downloads" tabindex="-1">Wire deep links and downloads <a class="header-anchor" href="#wire-deep-links-and-downloads" aria-label="Permalink to &quot;Wire deep links and downloads&quot;">​</a></h2><p>A deep link looks like <code>saas://open/notifications</code>; substitute your registered absolute route. The parser rejects external URLs, protocol-relative paths, backslashes and raw whitespace. A single-instance lock sends valid targets to the existing window. The destination API still authenticates and authorizes; the link is not a credential.</p><p>Downloads initiated by same-origin pages go to the <code>SaasTemplate</code> subdirectory of system downloads, overridden by <code>SAAS_DESKTOP_DOWNLOADS_DIR</code>. Main-process filename sanitization and numbered collisions prevent overwriting. Cross-origin page downloads are canceled. Your Files client obtains authorized bytes through the backend and triggers a page download without placing content in IPC.</p><h2 id="failures-and-checks" tabindex="-1">Failures and checks <a class="header-anchor" href="#failures-and-checks" aria-label="Permalink to &quot;Failures and checks&quot;">​</a></h2><p>Connectivity failure or renderer crashes show a local error page. Reconnect returns to the failed application address using the shell&#39;s saved language and theme. Check load failure, retry, invalid deep links and cross-origin download rejection:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/desktop/src/ipc-contract.test.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @saas/desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop-smoke</span></span></code></pre></div><p>Contract tests need no GUI. <code>desktop-smoke</code> creates a real isolated application stack and drives Electron with Playwright to check Sessions, navigation, downloads and recovery; it needs a display or xvfb. Add a focused journey for your business pages while keeping complete role matrices in backend tests.</p><p>Backend-only and documentation-content changes do not need Electron validation. Select these checks when changing platform wiring or delivering a desktop journey. Installers, automatic updates and platform signing are not provided; connect the built <code>dist/main.cjs</code> to a separate Electron packaging pipeline.</p><p>Next: <a href="./add-example">Application-shell contribution contract</a>. Long-term client resource observation is a separate soak task.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/tutorials/20-electron-shell.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,24)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
